// Config: every setting comes from environment variables, with safe defaults (dry run ON, approval OFF).
const env = (k, d = '') => ($env[k] === undefined || $env[k] === null || $env[k] === '' ? d : String($env[k]));
const bool = (k, d) => /^(1|true|yes|on)$/i.test(env(k, d ? 'true' : 'false'));
const num = (k, d) => (isNaN(parseFloat(env(k, ''))) ? d : parseFloat(env(k, '')));

let trigger = 'manual';
try { if ($('Run Now (Webhook)').isExecuted) trigger = 'webhook'; } catch (e) {}
try { if ($('Daily Schedule').isExecuted) trigger = 'schedule'; } catch (e) {}

// Optional shared secret for the webhook trigger
const hook = trigger === 'webhook' ? $('Run Now (Webhook)').first().json : {};
if (trigger === 'webhook' && env('RUN_TOKEN')) {
  const got = hook.headers?.['x-run-token'] || hook.query?.token;
  if (got !== env('RUN_TOKEN')) throw new Error('CONFIG_ERROR: invalid or missing run token');
}
const webhookOverrides = hook.query || {};

const provider = env('LLM_PROVIDER', 'openai').toLowerCase();
const cfg = {
  dryRun: bool('DRY_RUN', true),
  approvalMode: webhookOverrides.approval !== undefined ? /^(1|true|yes|on)$/i.test(String(webhookOverrides.approval)) : bool('APPROVAL_MODE', false),
  timezone: env('GENERIC_TIMEZONE', 'Asia/Jakarta'),
  site: {
    canonicalBase: 'https://www.placidway.com',
    fetchBase: env('PW_BASE_URL', 'https://www.placidway.com').replace(/\/$/, ''),
    userAgent: env('PW_USER_AGENT', 'PlacidWayFBDemoBot/1.0 (+assessment demo; contact hello@herin.id)'),
    minDelaySeconds: Math.max(1, num('PW_MIN_DELAY_SECONDS', 1.1)),
  },
  sitemaps: {
    article: '/1/sitemap_articles.xml',
    package: '/1/sitemap_packages.xml',
    answer: '/sitemap/1/sitemap_answers.xml',
  },
  rotation: env('CONTENT_ROTATION', 'article,package,answer,article,package,answer,article').split(',').map((s) => s.trim()), // Mon..Sun
  contentTypeOverride: webhookOverrides.type || env('CONTENT_TYPE_OVERRIDE', ''),
  candidateWindow: num('CANDIDATE_WINDOW', 30),
  skipUrlPattern: env('SKIP_URL_PATTERN', ''), // optional brand-safety regex, e.g. autism|terminal
  varietyLookback: num('VARIETY_LOOKBACK', 3),
  dedupeDryRun: bool('DEDUPE_INCLUDE_DRY_RUN', true),
  sourceMaxChars: num('SOURCE_MAX_CHARS', 9000),
  imageVariant: webhookOverrides.image || env('IMAGE_VARIANT', 'original'), // original = raw CDN file, og = PlacidWay's 1200x630 social crop, none = link post
  allowPrices: bool('ALLOW_PRICES', false),
  maxRewrites: num('MAX_REWRITES', 1),
  maxCharsBeforeLink: num('MAX_CHARS_BEFORE_LINK', 500),
  llm: {
    provider: provider === 'anthropic' ? 'anthropic' : 'openai',
    baseUrl: env('LLM_BASE_URL', provider === 'anthropic' ? 'https://api.anthropic.com' : 'https://api.openai.com/v1'),
    model: env('LLM_MODEL', provider === 'anthropic' ? 'claude-sonnet-4-5' : 'gpt-4o-mini'),
    reviewModel: env('LLM_REVIEW_MODEL', ''),
    apiKey: env('LLM_API_KEY', ''),
    temperature: num('LLM_TEMPERATURE', 0.4),
    jsonMode: bool('LLM_JSON_MODE', true),
    maxTries: num('LLM_MAX_TRIES', 3),
    timeoutMs: num('LLM_TIMEOUT_MS', 60000),
  },
  fb: {
    graphBase: env('FB_GRAPH_BASE_URL', 'https://graph.facebook.com').replace(/\/$/, ''),
    version: env('FB_GRAPH_VERSION', 'v24.0'),
    pageId: env('FB_PAGE_ID', ''),
    pageName: env('FB_PAGE_NAME', 'NeuPix'),
    allowedPageIds: env('FB_ALLOWED_PAGE_IDS', env('FB_PAGE_ID', '')).split(',').map((s) => s.trim()).filter(Boolean),
    scheduleDelayMinutes: webhookOverrides.schedule !== undefined ? +webhookOverrides.schedule || 0 : num('FB_SCHEDULE_DELAY_MINUTES', 0),
    hasToken: !!env('FB_PAGE_TOKEN', ''),
  },
  review: { webhookUrl: env('REVIEW_WEBHOOK_URL', env('ALERT_WEBHOOK_URL', '')), format: env('WEBHOOK_FORMAT', 'slack') },
  alert: { webhookUrl: env('ALERT_WEBHOOK_URL', ''), format: env('WEBHOOK_FORMAT', 'slack') },
};
if (cfg.llm.apiKey) cfg.llm.apiKeySet = true;

// Safety checks before doing any work
const problems = [];
if (!cfg.dryRun) {
  if (!cfg.fb.pageId) problems.push('FB_PAGE_ID is required when DRY_RUN=false');
  if (!cfg.fb.hasToken) problems.push('FB_PAGE_TOKEN is required when DRY_RUN=false');
  if (cfg.fb.pageId && !cfg.fb.allowedPageIds.includes(cfg.fb.pageId)) problems.push('FB_PAGE_ID is not in FB_ALLOWED_PAGE_IDS (publishing is restricted to your own test page)');
}
if (!cfg.llm.apiKey) problems.push('LLM_API_KEY is not set');
if (problems.length) throw new Error('CONFIG_ERROR: ' + problems.join('; '));

const run = { id: String($execution.id), trigger, startedAt: new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC', mode: (cfg.dryRun ? 'dry_run' : 'live') + (cfg.approvalMode ? '+approval' : '+auto') };
// Never carry the API key forward in item data (execution logs) - nodes read it from $env when needed.
delete cfg.llm.apiKey;
return [{ json: { cfg, run } }];

// Plan Run: choose today's content type (weekly rotation) and load what was already posted.
const { cfg, run } = $('Config').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && r.url);
const posted = rows.filter((r) => cfg.dedupeDryRun || r.status !== 'dry_run');
posted.sort((a, b) => String(b.posted_at).localeCompare(String(a.posted_at)));

const weekday = new Date().toLocaleDateString('en-US', { weekday: 'short', timeZone: cfg.timezone });
const idx = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].indexOf(weekday);
let contentType = cfg.contentTypeOverride || cfg.rotation[idx] || 'article';
if (!cfg.sitemaps[contentType]) contentType = 'article';

const sitemapPath = cfg.sitemaps[contentType];
return [{ json: {
  cfg, run,
  plan: { weekday, contentType, sitemapPath, sitemapUrl: cfg.site.canonicalBase + sitemapPath, sitemapFetchUrl: cfg.site.fetchBase + sitemapPath,
          robotsFetchUrl: cfg.site.fetchBase + '/robots.txt' },
  history: {
    postedUrls: posted.map((r) => r.url),
    recentCategories: posted.slice(0, cfg.varietyLookback).map((r) => r.category),
    recentTypes: posted.slice(0, cfg.varietyLookback).map((r) => r.content_type),
  },
} }];

// Apply robots.txt: parse the rules for our user agent (falls back to '*'), honour Crawl-delay,
// and refuse to continue if the sitemap itself is disallowed.
const state = $('Plan Run (Rotation)').first().json;
const res = $input.first().json;
const text = String(res.data ?? res.body ?? '');
if ((res.statusCode || 200) >= 400 && res.statusCode !== 404) throw new Error(`SOURCE_DOWN: robots.txt returned HTTP ${res.statusCode}`);

function parseRobots(txt, ua) {
  const groups = []; let cur = null; let lastWasUA = false;
  for (let line of txt.split(/\r?\n/)) {
    line = line.replace(/#.*$/, '').trim(); if (!line) continue;
    const m = line.match(/^([A-Za-z-]+)\s*:\s*(.*)$/); if (!m) continue;
    const key = m[1].toLowerCase(), val = m[2].trim();
    if (key === 'user-agent') { if (!lastWasUA) { cur = { agents: [], rules: [], crawlDelay: null }; groups.push(cur); } cur.agents.push(val.toLowerCase()); lastWasUA = true; continue; }
    lastWasUA = false; if (!cur) continue;
    if (key === 'allow' || key === 'disallow') { if (val) cur.rules.push({ allow: key === 'allow', path: val }); }
    else if (key === 'crawl-delay') cur.crawlDelay = parseFloat(val);
  }
  const token = ua.toLowerCase().split('/')[0];
  return groups.find((g) => g.agents.some((a) => a !== '*' && token.includes(a))) || groups.find((g) => g.agents.includes('*')) || { rules: [], crawlDelay: null };
}
const group = res.statusCode === 404 ? { rules: [], crawlDelay: null } : parseRobots(text, state.cfg.site.userAgent);
const robots = { rules: group.rules, crawlDelay: group.crawlDelay };

// Longest-match wins; Allow wins ties (RFC 9309). Supports * and $ wildcards.
function isAllowed(path, rules) {
  let best = null;
  for (const r of rules) {
    const re = new RegExp('^' + r.path.replace(/[.+?^{}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\\\$$/, '$'));
    if (re.test(path) && (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.allow))) best = r;
  }
  return !best || best.allow;
}
if (!isAllowed(state.plan.sitemapPath, robots.rules)) throw new Error(`ROBOTS_DISALLOWED: ${state.plan.sitemapPath} is disallowed by robots.txt`);
const throttleSeconds = Math.max(state.cfg.site.minDelaySeconds, robots.crawlDelay || 0);
return [{ json: { ...state, robots, throttleSeconds } }];

// Select Item: parse the sitemap, drop anything disallowed or already posted, prefer the newest
// item whose treatment category differs from the last few posts (variety rule).
const state = $('Apply robots.txt').first().json;
const xml = String($input.first().json.data ?? $input.first().json.body ?? '');
if (!/<urlset/i.test(xml)) throw new Error('PARSE_FAILED: sitemap response is not a <urlset> document' + (/just a moment|cf-mitigated|challenge/i.test(xml) ? ' (looks like a Cloudflare challenge page)' : ''));

function isAllowed(path, rules) {
  let best = null;
  for (const r of rules) {
    const re = new RegExp('^' + r.path.replace(/[.+?^{}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\\\$$/, '$'));
    if (re.test(path) && (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.allow))) best = r;
  }
  return !best || best.allow;
}
const CATEGORIES = [
  ['cardiac', /cardiac|heart|cabg|coronary|valve|angioplasty/],
  ['cancer', /cancer|oncolog|tumou?r|lymphoma|leukemia|carcinoma|melanoma/],
  ['neuro', /huntington|parkinson|alzheimer|autism|stroke|multiple-sclerosis|\bms\b|neuro|\bals\b|cerebral/],
  ['stem-cell', /stem-?cell|regenerative|\bprp\b|exosome|cellular/],
  ['cosmetic', /liposuction|tummy|abdominoplasty|plastic|cosmetic|breast|rhinoplasty|facelift|\bbbl\b|body-contour|eyelid|mommy/],
  ['bariatric', /bariatric|gastric|weight-loss|sleeve|obesity|ozempic|mounjaro|glp/],
  ['dental', /dental|implant|veneer|teeth|tooth|crown|all-on/],
  ['orthopedic', /knee|hip|spine|orthop|joint|shoulder|arthritis/],
  ['fertility', /ivf|fertility|surrogacy|egg-freez|infertility/],
  ['hair', /hair/], ['eye', /lasik|eye|cataract|vision/],
];
const categoryOf = (url) => { const s = url.toLowerCase(); for (const [c, re] of CATEGORIES) if (re.test(s)) return c; return 'other'; };

const entries = [];
for (const m of xml.matchAll(/<url>([\s\S]*?)<\/url>/g)) {
  const block = m[1];
  const loc = (block.match(/<loc>\s*([^<\s]+)\s*<\/loc>/) || [])[1];
  if (!loc) continue;
  const lastmod = (block.match(/<lastmod>\s*([^<\s]+)\s*<\/lastmod>/) || [])[1] || '';
  const image = (block.match(/<image:loc>\s*([^<\s]+)\s*<\/image:loc>/) || [])[1] || '';
  const id = +((loc.match(/\/(\d+)\//) || [])[1] || 0);
  entries.push({ url: loc.replace(/&amp;/g, '&'), lastmod, sitemapImage: image.replace(/&amp;/g, '&'), id });
}
const posted = new Set(state.history.postedUrls);
const base = state.cfg.site.canonicalBase;
const fresh = entries
  .filter((e) => e.url.startsWith(base + '/'))
  .filter((e) => isAllowed(e.url.slice(base.length), state.robots.rules))
  .filter((e) => !posted.has(e.url))
  .filter((e) => !state.cfg.skipUrlPattern || !new RegExp(state.cfg.skipUrlPattern, 'i').test(e.url))
  .sort((a, b) => b.lastmod.localeCompare(a.lastmod) || b.id - a.id)
  .slice(0, state.cfg.candidateWindow)
  .map((e) => ({ ...e, category: categoryOf(e.url) }));
if (!fresh.length) throw new Error(`NO_NEW_CONTENT: all ${entries.length} '${state.plan.contentType}' sitemap items are already posted or disallowed`);

const recent = new Set(state.history.recentCategories);
const pick = fresh.find((e) => !recent.has(e.category)) || fresh[0];
const item = { ...pick, contentType: state.plan.contentType, fetchUrl: state.cfg.site.fetchBase + pick.url.slice(base.length),
  selection: { sitemapEntries: entries.length, candidates: fresh.length, varietySkipped: fresh.indexOf(pick), avoidedCategories: [...recent] } };
return [{ json: { ...state, item } }];

// ---- shared helpers (inlined by scripts/build_workflows.py) ----
const decodeEntities = (s) => String(s || '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&#x27;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&rsquo;|&lsquo;/g, "'").replace(/&ldquo;|&rdquo;/g, '"')
  .replace(/&ndash;/g, '-').replace(/&mdash;/g, '-').replace(/&hellip;/g, '...')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)));
const norm = (s) => decodeEntities(s).toLowerCase().replace(/[\u2018\u2019\u201c\u201d]/g, "'").replace(/[^a-z0-9]+/g, ' ').trim();
const nowIso = () => new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';

// Parse Page: detect bot walls, then extract title, summary, featured image and the main body text.
const state = $('Select Item').first().json;
const res = $input.first().json;
const html = String(res.data ?? res.body ?? '');
const status = res.statusCode || 200;
const headers = res.headers || {};
if (headers['cf-mitigated'] || /<title>\s*Just a moment|challenge-platform|cf-chl-/i.test(html)) {
  throw new Error(`SOURCE_BLOCKED: Cloudflare challenge on ${state.item.url} (HTTP ${status}). The host IP is being challenged; run from a different network or ask PlacidWay to allow-list the bot.`);
}
if (status >= 400) throw new Error(`SOURCE_DOWN: ${state.item.url} returned HTTP ${status}`);

const meta = (key) => {
  const a = html.match(new RegExp(`<meta[^>]+(?:property|name)=["']${key}["'][^>]*content=["']([^"']*)["']`, 'i'));
  const b = html.match(new RegExp(`<meta[^>]+content=["']([^"']*)["'][^>]*(?:property|name)=["']${key}["']`, 'i'));
  return decodeEntities((a || b || [])[1] || '').trim();
};
const strip = (s) => decodeEntities(String(s).replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const h1 = strip((html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || [])[1] || '');
const docTitle = strip((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '');
const canonical = (html.match(/<link[^>]+rel=["']canonical["'][^>]*href=["']([^"']+)["']/i) || [])[1] || state.item.url;

// Main content = everything after the H1, cut at the first block that is not part of the page body
// (disclaimer, references, quote form, related listings, footer). Related listings carry other prices,
// so cutting them out is part of the "no invented prices" guardrail.
let main = html;
const h1Pos = html.search(/<\/h1>/i);
if (h1Pos > -1) main = html.slice(h1Pos + 5);
// Drop share/quote popups first: on live pages they sit right after the H1 and would end the body early.
main = main.replace(/<!--[\s\S]*?-->/g, ' ').replace(/<(script|style|noscript|svg)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<[^>]*>/g, (t) => t.replace(/\s+/g, ' ')); // multi-line tags would leak into the text once split by line
const STOP = /<(h[1-6]|div|section|p|strong|span)[^>]*>\s*(Medical Disclaimer|References|Request your Free Quote|About Article|Trusted Medical Tourism Platform|Unlock the Best|Related (Articles|Packages)|Share this listing)\b/gi;
// Cut at the first stop marker that comes after real content (>= 600 chars of text), skipping early popups.
for (const m of main.matchAll(STOP)) {
  if (strip(main.slice(0, m.index)).length >= 600) { main = main.slice(0, m.index); break; }
}
main = main
  .replace(/<(script|style|noscript|svg|form|nav|footer|header|iframe)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<\/(td|th)>/gi, ' | ')
  .replace(/<(br|\/p|\/h[1-6]|\/li|\/tr|\/div|\/table|\/ul|\/ol)[^>]*>/gi, '\n')
  .replace(/<li[^>]*>/gi, '\n- ');
const body = main.split('\n')
  .map((l) => strip(l).replace(/\s*\|\s*$/, ''))
  .filter((l) => l && l !== '-' && !/^(copy link|share this|https?:\/\/\S+)$/i.test(l))
  .join('\n')
  .slice(0, 20000);
if (body.length < 400) throw new Error(`PARSE_FAILED: main content too short (${body.length} chars) on ${state.item.url} - page layout may have changed`);

// Featured image: og:image, else the sitemap <image:loc>, else first content image.
let image = meta('og:image') || state.item.sitemapImage || ((main.match(/<img[^>]+src=["'](https:[^"']+)["']/i) || [])[1] || '');
if (state.cfg.imageVariant === 'original') {
  const m = image.match(/\/cdn-cgi\/image\/[^/]+\/(https?:\/\/.+)$/); // unwrap PlacidWay's CDN resizer to the original file
  if (m) image = m[1];
}
if (state.cfg.imageVariant === 'none') image = ''; // forces a text+link post (/feed)
const description = meta('og:description') || meta('description') || body.split('\n').find((l) => l.length > 80)?.slice(0, 300) || '';
const page = { title: h1 || meta('og:title') || docTitle, metaTitle: meta('og:title') || docTitle, description, image, canonical, body, bodyChars: body.length };
return [{ json: { ...state, page, attempt: 0, guardrailHistory: [] } }];

// ---- shared helpers (inlined by scripts/build_workflows.py) ----
const decodeEntities = (s) => String(s || '')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;|&#x27;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&rsquo;|&lsquo;/g, "'").replace(/&ldquo;|&rdquo;/g, '"')
  .replace(/&ndash;/g, '-').replace(/&mdash;/g, '-').replace(/&hellip;/g, '...')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n)).replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)));
const norm = (s) => decodeEntities(s).toLowerCase().replace(/[\u2018\u2019\u201c\u201d]/g, "'").replace(/[^a-z0-9]+/g, ' ').trim();
const nowIso = () => new Date().toISOString().replace('T', ' ').slice(0, 19) + ' UTC';

// ---- provider-agnostic LLM adapter (OpenAI-compatible or Anthropic) ----
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
function parseJsonLoose(text) {
  let t = String(text || '').trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  const a = t.indexOf('{'), b = t.lastIndexOf('}');
  if (a === -1 || b === -1) throw new Error('LLM_BAD_OUTPUT: no JSON object in model response');
  return JSON.parse(t.slice(a, b + 1));
}
async function callLLM(ctx, llm, system, user) {
  if (!llm.apiKey) throw new Error('LLM_CONFIG: LLM_API_KEY is not set');
  const base = llm.baseUrl.replace(/\/$/, '');
  let req;
  if (llm.provider === 'anthropic') {
    req = { method: 'POST', url: base + '/v1/messages', json: true, timeout: llm.timeoutMs,
      headers: { 'x-api-key': llm.apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: { model: llm.model, max_tokens: 1000, temperature: llm.temperature, system, messages: [{ role: 'user', content: user }] } };
  } else {
    const body = { model: llm.model, temperature: llm.temperature, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] };
    if (llm.jsonMode) body.response_format = { type: 'json_object' };
    req = { method: 'POST', url: base + '/chat/completions', json: true, timeout: llm.timeoutMs,
      headers: { Authorization: 'Bearer ' + llm.apiKey, 'content-type': 'application/json' }, body };
  }
  let lastErr;
  for (let attempt = 1; attempt <= llm.maxTries; attempt++) {
    try {
      const res = await ctx.helpers.httpRequest(req);
      const text = llm.provider === 'anthropic'
        ? (res.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('')
        : res.choices?.[0]?.message?.content;
      return { data: parseJsonLoose(text), raw: text, attempts: attempt };
    } catch (e) {
      lastErr = e;
      const m = String(e.message || e);
      const status = e.httpCode || e.statusCode || e.response?.status || +((m.match(/status code (\d{3})/) || [])[1] || 0);
      const retryable = !status || status === 429 || status >= 500 || /LLM_BAD_OUTPUT|Unexpected token|JSON/.test(m);
      if (!retryable || attempt === llm.maxTries) {
        throw new Error(`LLM_ERROR: ${llm.provider} call failed after ${attempt} attempt(s)` + (status ? ` (HTTP ${status})` : '') + `: ${m.slice(0, 300)}`);
      }
      await sleep(2000 * Math.pow(3, attempt - 1)); // 2s, 6s
    }
  }
  throw lastErr;
}

// ---- prompts ----
const WRITER_SYSTEM = `ROLE: WRITER
You write short, trustworthy Facebook posts that share one PlacidWay page (a medical tourism marketplace).
Use ONLY facts stated in the SOURCE. If something is not in the SOURCE, leave it out.

Structure:
- hook: one line, max 110 characters, curiosity or a question, no clickbait.
- lines: 2 to 4 short lines (max 120 characters each). Each line states one useful fact or takeaway from the SOURCE.
- cta: one calm line inviting people to read the full page (e.g. "Read the full guide:"). No pressure, no urgency, no "book now".
- hashtags: 3 to 5 relevant hashtags, CamelCase, no spaces.
- hook + lines + cta together must stay under 430 characters. Do NOT include any URL (it is added automatically).

Hard rules (a post that breaks one is rejected):
1. No medical claims and no outcome promises: never say a treatment cures, heals, reverses, fixes, eliminates, restores, guarantees, is proven, is safe/safest/best, is painless or risk-free, and never state success rates or results people will get. Use neutral wording such as "explores", "compares", "explains", "what to ask".
2. Prices: if ALLOW_PRICES is false, mention no prices, costs, savings or currency amounts at all. If true, only copy exact figures from the SOURCE.
3. No invented facts: every number, name, place and claim must appear in the SOURCE.
4. At most 2 emojis in the whole post.

Return ONLY a JSON object:
{"hook": "...", "lines": ["...", "..."], "cta": "...", "hashtags": ["#..."],
 "evidence": [{"line": 0, "quote": "verbatim sentence or phrase from SOURCE that supports lines[0]"}]}
Provide one evidence item per line; each quote must be copied exactly from the SOURCE.`;

const REVIEWER_SYSTEM = `ROLE: REVIEWER
You are a strict compliance reviewer for healthcare social media posts. Compare the POST with the SOURCE.
Flag an issue for anything in the POST that is:
- medical_claim: says or implies a treatment cures, heals, reverses, fixes, works, is safe/proven/best;
- outcome_promise: promises or implies results, recovery or success for the reader;
- invented_price: any price, cost, saving or currency amount that is not stated exactly in the SOURCE (or any price at all when ALLOW_PRICES is false);
- unsupported_fact: any fact, number, name or place not supported by the SOURCE;
